hljs.registerLanguage('dockerfile',function(e){return{name:'Dockerfile',aliases:['docker'],case_insensitive:true,keywords:'FROM MAINTAINER RUN CMD EXPOSE ENV ADD COPY ENTRYPOINT VOLUME USER WORKDIR ARG ONBUILD STOPSIGNAL HEALTHCHECK SHELL LABEL',contains:[e.HASH_COMMENT_MODE,e.APOS_STRING_MODE,e.QUOTE_STRING_MODE,e.NUMBER_MODE]}});